const learningResources=[
{id:'start',category:'Başlanğıc',title:'Robototexnikaya haradan başlamaq olar?',desc:'Mexanika, elektronika və proqramlaşdırma arasındakı əlaqəni anla, ilk layihəni seç.',read:'2 dəq',course:'robotics',sections:[['Üç sahə, bir sistem','Robotun fiziki quruluşu mexanikadır. Sensorlar və mühərriklər elektron hissəni təşkil edir. Proqram isə bu hissələrin hansı ardıcıllıqla işləyəcəyini müəyyən edir. Başlanğıcda hər üçünü kiçik tapşırıqlarla tanımaq daha aydın nəticə verir.'],['İlk layihəni kiçik saxla','İlk məqsəd kimi bir mühərriki hərəkət etdirmək, sonra düymə ilə idarə etmək və sonda bir sensor əlavə etmək seçilə bilər. Hər mərhələdə yalnız bir yeni element əlavə et.'],['İş qaydanı qur','Əvvəl məqsədi yaz, sonra komponentləri seç. Birləşmələri yoxla və yalnız bundan sonra qidalanma ver. Hər dəyişikliyi qeyd et; işləyən kodun bir nüsxəsini saxla.'],['Nəticəni izah et','Layihən işləyəndə özünə üç sual ver: giriş məlumatı nədir, proqram hansı qərarı verir və çıxışda nə baş verir? Bu üçlük robotun məntiqini anlamağa kömək edir.']]},
{id:'sensors',category:'Elektronika',title:'Sensor, kontroller və mühərrik necə işləyir?',desc:'Bir robotun “hiss etmə → qərar → hərəkət” dövrünü sadə nümunə ilə öyrən.',read:'2 dəq',course:'electronics',sections:[['Sensor məlumat toplayır','Məsafə sensoru obyektin yaxınlığını, işıq sensoru işıqlanmanı, xətt sensoru isə səthlərin işığı qaytarma fərqini ölçə bilər. Sensor robotun giriş məlumatını təmin edir.'],['Kontroller qərar verir','Arduino kimi kontroller proqramdakı qaydaları yerinə yetirir. Məsələn, məsafə müəyyən həddən azdırsa dayan, əks halda irəli get. Hədd qiyməti real şəraitdə sınaqla seçilir.'],['Sürücü gücü idarə edir','DC mühərriki adətən kontrollerin giriş-çıxış pininə birbaşa qoşmaq olmaz. Uyğun mühərrik sürücüsü kontrollerin siqnalına əsasən mühərrikin gücünü və istiqamətini idarə edir.'],['Sınaq bütün sistemi yoxlayır','Ölçmələri əvvəl serial monitorda müşahidə et. Sonra hərəkəti əlavə et. Sensorun yerləşməsi, qidalanma və səthin xüsusiyyətləri nəticəyə təsir edə bilər.']]},
{id:'lesson',category:'Müəllimlər üçün',title:'STEAM dərsi üçün sadə plan',desc:'Mövzu, problem, prototip və geribildirim: bir məşğələnin əsas mərhələləri.',read:'2 dəq',course:'steam',sections:[['1. Bir problem seç','Tapşırığı konkret sualla başlat: məhdud materiallarla kiçik yükü daşıyan körpünü necə qura bilərik? Məqsədi, materialları və vaxtı əvvəlcədən aydınlaşdır.'],['2. Təsəvvür və plan üçün vaxt ayır','Şagirdlərdən ideyalarını əvvəl eskizlə göstərmələrini istə. Cavabı birbaşa vermək əvəzinə “bu hissə yükü necə saxlayacaq?” kimi suallardan istifadə et.'],['3. Prototipi qur və sına','Hər komanda modelini eyni şərtlərdə yoxlasın. Yükü tədricən artırmaq və nəticələri qeyd etmək müşahidəni müqayisə etməyə imkan verir.'],['4. Təkmilləşdirməni dərsin hissəsinə çevir','Şagird ilk nəticədən sonra bir dəyişiklik seçsin və yenidən sınaqdan keçirsin. “Nə dəyişdi və niyə?” sualı yalnız işləyən modeli deyil, düşüncə prosesini də üzə çıxarır.'],['5. Yaşa uyğunlaşdır','Kiçik yaşlarda sadə materiallar və qısa mərhələlər seç. Daha böyük yaşlarda ölçü, məhdudiyyət və nəticə cədvəli əlavə etmək olar. İstifadə olunan alətlərə uyğun nəzarət təmin et.']]},
{id:'3dprint',category:'3D dizayn',title:'3D modeldən çapa: ilk yoxlamalar',desc:'Ölçü, divar qalınlığı və çap istiqaməti barədə başlanğıc qeydləri.',read:'2 dəq',course:'3d',sections:[['Ölçünü əvvəl düşün','Modelin hansı funksiyanı yerinə yetirəcəyini müəyyən et. Hazır hissə ilə birləşəcəksə, birləşmə yerinin ölçülərini yoxla. Təkcə ekranda yaxşı görünmək funksional uyğunluq demək deyil.'],['Divar qalınlığını yoxla','Çox nazik divarlar çap zamanı zəif və ya yararsız ola bilər. Uyğun qalınlıq materialdan, modelin funksiyasından, nozzle ölçüsündən və çap parametrlərindən asılıdır.'],['Çap istiqamətini seç','Modelin platformada necə yerləşməsi dayaq ehtiyacına, səth keyfiyyətinə və möhkəmliyinə təsir edir. Slicer önizləməsində hər qatın necə yaranacağını nəzərdən keçir.'],['Kiçik sınaqla başla','Böyük modeldən əvvəl yalnız birləşmə və ya kritik ölçüsü olan hissəni sınaq çapına vermək materiala və vaxta qənaət edir. Nəticəyə görə ölçünü düzəlt.']]}
];
const fullFaq=[
['Kurslar','Əvvəlcədən bilik lazımdır?','Başlanğıc istiqamətlər əsas anlayışlardan başlayır. İlkin biliklərini və məqsədini əlaqə zamanı müzakirə edərək uyğun proqram seçə bilərsən.'],
['Kurslar','Hansı kurs mənə uyğundur?','Robot qurmaq üçün Robototexnika, dövrələrlə işləmək üçün Arduino və elektronika, kodlaşdırma üçün Proqramlaşdırma, modelləmə üçün 3D dizayn istiqamətinə bax. Dərs keçmək istəyirsənsə, müəllim hazırlığını seç.'],
['Kurslar','Qiymət, müddət və qrafik necədir?','Dəqiq qiymət və dərs qrafiki proqram və format dəqiqləşdiriləndə bildirilir. Hər kursun səhifəsindəki müraciət düyməsindən məlumat ala bilərsən.'],
['Kurslar','Avadanlıq almaq lazımdır?','İstifadə ediləcək avadanlıq və onun təmin olunması seçilən proqram və dərs formatı üzrə əvvəlcədən razılaşdırılır. Müraciət zamanı bunu ayrıca soruşa bilərsən.'],
['Müəllim hazırlığı','STEAM müəllimi olmaq istəyənlər üçün proqram varmı?','Bəli. Metodika, yaşa uyğun fəaliyyətlər, robototexnika, Tinkercad, elektronika və nümunə dərsin hazırlanmasını birləşdirən proqram mövcuddur.'],
['Müəllim hazırlığı','Proqramda praktiki dərs planı hazırlanır?','Müəllim hazırlığı proqramının son modulunda dərs planlaşdırılması, fəaliyyətin təşkili, qiymətləndirmə və nümunə dərsin təqdimatı yer alır.'],
['Xidmətlər','Məktəb üçün laboratoriya qura bilərsiniz?','Laboratoriya xidməti məkan və ehtiyacın qiymətləndirilməsi, avadanlıq seçimi, yerləşim planı, quraşdırma və istifadəyə giriş təlimini əhatə edir.'],
['Xidmətlər','Hazır robotla yanaşı təlim də almaq olar?','Robotun və layihənin hazırlanması ilə birlikdə quruluşun, proqramın, sazlamanın və təqdimatın izahı üzrə təlim planlaşdırıla bilər.'],
['Xidmətlər','Yarış üçün hansı robotlar hazırlanır?','Xətt izləyən və mini sumo daxil olmaqla yarışın qaydalarına və texniki tələblərinə uyğun istiqamətlər müzakirə edilə bilər. İşə başlamazdan əvvəl yarış qaydaları qiymətləndirilir.'],
['Xidmətlər','Layihə üçün müraciətdə nə göndərim?','Məqsədini, istifadə şəraitini, varsa yarış qaydalarını, ölçü məhdudiyyətlərini və istədiyin nəticəni yaz. Mövcud sxem, kod və model barədə də məlumat verə bilərsən.']
];
function projectVisual(p){return p.art==='track'?'<div class="track-line"></div><span class="track-bot">EY</span>':p.art==='lab'?'<div class="mini-workstations"><span>3D</span><span>&lt;/&gt;</span><span>⚙</span></div>':p.art==='sumo'?'<div class="sumo-ring"><div class="sumo-bot"><i></i><b>EY</b></div></div>':'<div class="sensor-diagram"><span>◎</span><i>→</i><b>ARDUINO</b><i>→</i><span>◉</span></div>'}
function projectCard(p){return `<a class="project-card" href="#project/${p.id}"><div class="project-art ${p.art}"><small>${p.tag}</small>${projectVisual(p)}</div><div class="project-card-body"><span>${p.kind} · Nümunə istiqamət</span><h3>${p.title}</h3><p>${p.text}</p><b>Texniki yanaşmaya bax ↗</b></div></a>`}
function resourceCards(items){return items.map(r=>`<a class="resource-card" href="#resource/${r.id}"><span class="resource-category">${r.category} <small>${r.read} oxu</small></span><h3>${r.title}</h3><p>${r.desc}</p><b>Oxumağa başla ↗</b></a>`).join('')}
pages.projects=()=>`${head('Layihələr','Fikir. Prototip. İşləyən həll.','Birlikdə hazırlaya biləcəyimiz robot və layihə istiqamətlərini texniki yanaşmaları ilə kəşf et.')}<section class="wrap" style="padding-top:15px"><div class="editor-note"><span>◇</span><p>Aşağıdakı nümunələr layihə imkanlarını göstərir. Hər işin quruluşu və komponentləri konkret məqsədə görə seçilir.</p></div><div class="project-library">${projectLibrary.map(projectCard).join('')}</div></section>${cta()}`;
projectLibrary.forEach(p=>pages['project/'+p.id]=()=>`${head('Layihə istiqaməti',p.title,p.text)}<section class="wrap project-detail"><div><div class="project-art big ${p.art}"><small>${p.tag}</small>${projectVisual(p)}</div><h2>Texniki yanaşma</h2><p class="muted">${p.learn}</p><div class="delivery-steps">${p.steps.map((s,i)=>`<div><span>0${i+1}</span><p>${s}</p></div>`).join('')}</div><div class="notice">Bu, nümunə layihə istiqamətidir. Yekun texniki plan, işin həcmi və təlim ehtiyacı müraciətdən sonra dəqiqləşdirilir.</div></div><aside class="project-box"><small>ƏSAS HİSSƏLƏR</small><h3>Sistemə nə daxildir?</h3><ul>${p.parts.map(t=>`<li>${t}</li>`).join('')}</ul><a class="button" href="#contact?service=${p.service}">Layihəni müzakirə et ↗</a><a class="text-link" href="#course/${p.course}" style="display:inline-block;margin-top:22px">Əlaqəli kursa bax ↗</a></aside></section><div class="wrap page-end"><a class="text-link" href="#projects">← Bütün layihə istiqamətləri</a></div>${cta()}`);
pages.resources=()=>`${head('Resurslar','Bilik paylaşdıqca böyüyür.','Robototexnika, elektronika, STEAM tədrisi və 3D dizayn üzrə qısa, praktik başlanğıc materialları.')}<section class="wrap" style="padding-top:15px"><div class="resource-library">${resourceCards(learningResources)}</div><div class="learning-map"><div>${eyebrow('Öyrənmə xəritəsi')}<h2>İlk addımını seç.</h2><p>Bir mövzunu anla, kiçik tapşırıqda yoxla və sonra öz layihəndə tətbiq et.</p></div><div class="map-links"><a href="#resource/start">01 <span>Robototexnikanın əsasları</span> ↗</a><a href="#resource/sensors">02 <span>Sensor və idarəetmə</span> ↗</a><a href="#resource/3dprint">03 <span>Dizayn və prototip</span> ↗</a><a href="#resource/lesson">04 <span>Öyrəndiyini öyrət</span> ↗</a></div></div></section>${cta()}`;
learningResources.forEach(r=>pages['resource/'+r.id]=()=>`${head(r.category,r.title,r.desc)}<section class="wrap article-layout"><article class="guide"><div class="guide-meta"><span>EYROBOTX / Tədris qeydləri</span><span>${r.read} oxu</span></div>${r.sections.map((s,i)=>`<section id="guide-section-${i}"><span class="guide-number">0${i+1}</span><h2>${s[0]}</h2><p>${s[1]}</p></section>`).join('')}<div class="guide-next"><h3>Praktik öyrənməyə davam et.</h3><p>Mövzunu addım-addım proqram və praktik tapşırıqlarla öyrənmək üçün əlaqəli kursu kəşf et.</p><a class="button" href="#course/${r.course}">Kurs proqramına bax ↗</a></div></article><aside class="guide-aside"><small>BU MATERİALDA</small>${r.sections.map((s,i)=>`<button type="button" data-guide-section="${i}"><span>0${i+1}</span> ${s[0]}</button>`).join('')}<a class="text-link" href="#resources">← Bütün resurslar</a></aside></section>`);
function faqResults(q=''){const normalized=q.toLocaleLowerCase('az');const found=fullFaq.filter(x=>x.join(' ').toLocaleLowerCase('az').includes(normalized));return found.length?found.map(x=>`<details class="help-question"><summary><span>${x[0]}</span>${x[1]}</summary><p>${x[2]}</p></details>`).join(''):'<div class="no-results"><h3>Uyğun sual tapılmadı.</h3><p>Başqa sözlə axtar və ya sualını birbaşa bizə göndər.</p><a class="button" href="#contact">Sualını göndər ↗</a></div>'}
pages.faq=()=>`${head('Sual-cavab','Cavabını rahat tap.','Kurslar, müəllim hazırlığı, laboratoriyalar və robot layihələri haqqında ən çox soruşulanlar.')}<section class="wrap help-layout" style="padding-top:15px"><div><label for="faq-search">Sual və ya mövzu axtar</label><input id="faq-search" type="search" placeholder="Məsələn: laboratoriya, qiymət, müəllim…"><p id="faq-count" class="fine" role="status">${fullFaq.length} sual</p><div id="faq-results">${faqResults()}</div></div><aside class="project-box"><small>BİRLİKDƏ DƏQİQLƏŞDİRƏK</small><h3>Başqa sualın var?</h3><p>Seçəcəyin kurs və ya layihənin texniki tərəfi barədə danışa bilərik.</p><a class="button" href="#contact">Bizə yaz ↗</a></aside></section>`;
const homeProfessional=pages.home;
pages.home=()=>homeProfessional().replace(projectExamples(),`<section class="wrap"><div class="section-head"><div>${eyebrow('Layihə istiqamətləri')}<h2>Mühəndislik iş başında.</h2></div><a class="text-link" href="#projects">Bütün istiqamətlər ↗</a></div><div class="project-library compact">${projectLibrary.slice(0,2).map(projectCard).join('')}</div></section>`).replace(faq(),`<section class="wrap"><div class="section-head"><div>${eyebrow('Bilik mərkəzi')}<h2>Öyrənmək üçün yaxşı başlanğıc.</h2></div><a class="text-link" href="#resources">Bütün resurslar ↗</a></div><div class="resource-library home-resources">${resourceCards(learningResources.slice(0,3))}</div></section>`+faq().replace('Sualını göndər ↗','Bütün suallara bax ↗').replace('href="#contact">Bütün suallara bax','href="#faq">Bütün suallara bax'));
const coursesProfessional=pages.courses;
pages.courses=()=>coursesProfessional().replace('<div class="filters"','<div class="course-search"><label for="course-search">Marağına uyğun kursu tap</label><input id="course-search" type="search" placeholder="Arduino, müəllim, 3D dizayn…"><p id="course-count" class="fine" role="status">'+courses.length+' kurs</p></div><div class="filters"');
function filterCoursesProfessional(){const search=document.querySelector('#course-search');if(!search)return;const term=search.value.toLocaleLowerCase('az').trim(),category=document.querySelector('.filter.active')?.dataset.filter||'Hamısı';const filtered=courses.filter(c=>(category==='Hamısı'||c.category===category)&&[c.title,c.desc,...courseDetails[c.id].tools].join(' ').toLocaleLowerCase('az').includes(term));document.querySelector('#course-results').innerHTML=filtered.length?cards(filtered):'<div class="no-results"><h3>Uyğun kurs tapılmadı.</h3><p>Axtarışı dəyiş və ya “Hamısı” istiqamətini seç.</p></div>';document.querySelector('#course-count').textContent=filtered.length+' kurs tapıldı'}
const aboutProfessional=pages.about;
pages.about=()=>aboutProfessional().replace(cta(),`<section class="wrap"><div class="section-head"><div>${eyebrow('Bir-birini tamamlayan bacarıqlar')}<h2>Bir ideyaya dörd tərəfdən baxırıq.</h2></div></div><div class="expertise-grid">${[['01','Robototexnika','LEGO, Makeblock, Micro:bit və Arduino ilə mexanizm və idarəetmə.'],['02','Proqramlaşdırma','C++, C# və Arduino ilə alqoritmdən işləyən proqrama.'],['03','Elektronika','Sensorlar, mühərriklər və elektron komponentlərdən vahid sistemə.'],['04','3D dizayn','Tinkercad və Onshape ilə model, detal və prototip.']].map(x=>`<div><span>${x[0]}</span><h3>${x[1]}</h3><p>${x[2]}</p></div>`).join('')}</div></section>`+cta());
function postProfessionalRender(){const page=(location.hash.slice(1)||'home').split('?')[0];const project=page.startsWith('project/')?projectLibrary.find(p=>'project/'+p.id===page):null;const resource=page.startsWith('resource/')?learningResources.find(r=>'resource/'+r.id===page):null;const titles={projects:'Layihə istiqamətləri',resources:'Resurslar',faq:'Sual-cavab'};if(titles[page]||project||resource)document.title=(titles[page]||project?.title||resource?.title)+' — EYROBOTX';if(project||resource){const active=project?'projects':'resources';document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+active))}document.querySelectorAll('nav a').forEach(a=>{if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.querySelector('#back-top').hidden=true}
window.addEventListener('hashchange',postProfessionalRender);
document.addEventListener('input',e=>{if(e.target.id==='course-search')filterCoursesProfessional();if(e.target.id==='faq-search'){document.querySelector('#faq-results').innerHTML=faqResults(e.target.value);document.querySelector('#faq-count').textContent=document.querySelectorAll('#faq-results details').length+' sual tapıldı'}});
document.addEventListener('click',e=>{const section=e.target.closest('[data-guide-section]');if(section)document.querySelector('#guide-section-'+section.dataset.guideSection)?.scrollIntoView({behavior:'smooth',block:'start'});if(e.target.closest('[data-filter]'))filterCoursesProfessional();if(e.target.closest('#back-top'))window.scrollTo({top:0,behavior:'smooth'})});
window.addEventListener('scroll',()=>{document.querySelector('#back-top').hidden=window.scrollY<650},{passive:true});
render();postProfessionalRender();
